/* csrc/enemy_macro.c -- E-14 (signatures.toml module; the epic's own math
 * lands with its build card).
 * Skeleton generated by scripts/specfactory/sig_table.py so the fenced suite
 * fails red on assertions, not on a missing symbol, and so the build harness
 * has a file to read; every body below is a STUB the build card replaces. */
/* PRIVATE LAYOUT, verbatim from csrc/om_internal.h (already included below).
 * Use exactly these member names; there are no others.
 * #define OM_MAX_NEIGHBORS 32
 * #define OM_DAMAGE_HISTORY_CAP 64
 *
 * typedef struct {
 *     om_tier  tier;
 *     double   military, economy, tension, population;
 *     double   econ_phase, tension_phase;
 *     double   prev_econ_osc, prev_tension_osc;
 *     int32_t  faction_id;
 *     uint32_t neighbors[OM_MAX_NEIGHBORS];
 *     uint32_t n_neighbors;
 *     om_drift_row last_drift;
 *
 *     / * ALG-11 damage history (om_region_add_damage / om_region_damage_history,
 *      * ouroboros_sim.h ~line 254): a ring of (tick, military_loss, economy_loss)
 *      * entries, one per recorded attack-resolution loss, oldest overwritten past
 *      * OM_DAMAGE_HISTORY_CAP. Persists across ticks; never reset in sim.c. The
 *      * reader sums entries with tick within DAMAGE_HISTORY_WINDOW = 150 of the
 *      * current world tick (docs/bible/algorithms.md ALG-11; R-034-07). * /
 *     uint64_t damage_tick[OM_DAMAGE_HISTORY_CAP];
 *     double   damage_military[OM_DAMAGE_HISTORY_CAP];
 *     double   damage_economy[OM_DAMAGE_HISTORY_CAP];
 *     uint32_t damage_head, damage_len;
 * } om_region;
 *
 * struct om_world {
 *     uint32_t n_regions;
 *     uint64_t seed;
 *     uint64_t tick;
 *     int      trace_on;
 *     int      inject;
 *     om_region *regions;
 *     double   faction_mod[OM_MAX_FACTIONS][OM_F_COUNT];
 *     om_trace_row *trace;
 *     uint64_t trace_len, trace_cap;
 *
 *     / * E-05 faction, ownership, typed edges, and RNG state.
 *      * features[] is sized for every om_feature id (OM_FEAT_EVENTS ..
 *      * OM_FEAT_TACTICAL, 9 today); bump alongside a new om_feature value. * /
 *     int          features[9];
 *     double       faction_budget[OM_MAX_FACTIONS];
 *     double       faction_budget_snapshot[OM_MAX_FACTIONS];
 *     double       faction_tech[OM_MAX_FACTIONS];
 *     double       faction_confidence[OM_MAX_FACTIONS];
 *     om_archetype faction_archetype[OM_MAX_FACTIONS];
 *     om_stance    faction_stance[OM_MAX_FACTIONS][OM_MAX_FACTIONS];
 *     double       faction_tech_attack[OM_MAX_FACTIONS];
 *     double       faction_tech_defense[OM_MAX_FACTIONS];
 *     double       faction_tech_economy[OM_MAX_FACTIONS];
 *     int          faction_used[OM_MAX_FACTIONS];
 *     uint32_t     faction_n;
 *     int64_t     *region_held_since;
 *     om_edge_type region_edge[64][64];
 *     uint64_t     rng_state, rng_inc;
 *     double       rng_forced[4096];
 *     uint32_t     rng_forced_head, rng_forced_len;
 *
 *     / * E-05 decision and resolution state * /
 *     om_decision        decisions[64];
 *     uint32_t           decisions_n;
 *     om_telegraph       telegraphs[64];
 *     uint32_t           telegraphs_n;
 *     om_attack_result   attacks[64];
 *     uint32_t           attacks_n;
 *     om_collision       collisions[64];
 *     uint32_t           collisions_n;
 *     om_reinforce       reinforces[64];
 *     uint32_t           reinforces_n;
 *     om_colonize_result colonizations[64];
 *     uint32_t           colonizations_n;
 *     om_friction        frictions[64];
 *     uint32_t           frictions_n;
 *     om_admin_roll      admin_rolls[64];
 *     uint32_t           admin_rolls_n;
 *
 *     / * event queue, shared with E-04 (ouroboros_sim.h ~line 454): entries are
 *      * queued by E-05 (conquest-unrest, admin-separatist chains) and resolved
 *      * by E-04 (ALG-36). Persists across ticks; never reset in sim.c. * /
 *     om_queued_event    event_queue[64];
 *     uint32_t           event_queue_n;
 * };
 */
#include "ouroboros_sim.h"
#include "om_internal.h"
#include "om_constants.h"
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* See also: om_move_get_canvas_size in csrc/tactical_move.c (internal, not in the header). */
void om_move_get_canvas_size(om_world *w, double *width, double *height);

/* B13 (E-14): all state for this module lives in w->macro_state /
 * w->macro_state_free, same convention as w->tactical_state /
 * w->mission_state (F2i slot; csrc/mission.c's om_mis()/om_mis_state_free
 * is the mirrored pattern). The one exception is the bus vocabulary
 * (om_macro_bus_register_vocab / om_macro_validate_bus_flag): the ABI
 * gives both no om_world* at all, so they cannot be per-world state --
 * they are a script-authoring schema, not simulation state, and are kept
 * in file statics for that reason (never touched per tick, never saved). */

enum { OM_MACRO_ADVANCE, OM_MACRO_DEFEND, OM_MACRO_PATROL, OM_MACRO_AMBUSH, OM_MACRO_RETREAT };
enum { OM_MACRO_MOD_CAUTIOUS, OM_MACRO_MOD_AGGRESSIVE, OM_MACRO_MOD_PHASED };
enum { OM_MACRO_CMD_MOVE, OM_MACRO_CMD_ATTACK_MOVE, OM_MACRO_CMD_ATTACK_TARGET, OM_MACRO_CMD_ACTIVATE_ABILITY };
enum { OM_MACRO_TRANS_THRESHOLD, OM_MACRO_TRANS_TIMER, OM_MACRO_TRANS_HOOK, OM_MACRO_TRANS_RETREAT, OM_MACRO_TRANS_ESCALATE };
enum { OM_MACRO_DIR_N, OM_MACRO_DIR_E, OM_MACRO_DIR_S, OM_MACRO_DIR_W, OM_MACRO_DIR_COUNT };

#define OM_MACRO_MAX_FORCES 64
#define OM_MACRO_MAX_BUS_FLAGS 32
#define OM_MACRO_MAX_VOCAB 32
#define OM_MACRO_MAX_HOOK_BINDS 64
#define OM_MACRO_MAX_REPLAY 4096
#define OM_MACRO_CAPTURE_BUF_CAP 65536
#define OM_MACRO_BUS_NAME_CAP 64
#define OM_MACRO_UNIT_TYPE_SLOTS 8
/* Not in om_constants.h: Q-120-01 closed (b), no posture differentiation. */
#define OM_MACRO_SPEED_MULT_CAUTIOUS 1.0
#define OM_MACRO_SPEED_MULT_AGGRESSIVE 1.0
/* OM_MACRO_ROUT_HP_THRESHOLD 0.35 and OM_MACRO_EXTERNAL_REINFORCEMENT_PROB 0.21
 * now in csrc/om_constants.h (ALG-76, Q-120-03, Q-124-03, CONST-1 promotion;
 * values updated from 0.20/0.07 by Westley 2026-09-26). */
/* ALG-75 (Q-124-02): count of unit types in the standard wave composition.
 * OM_UNIT_TYPE_COUNT is file-static in unit.c; we mirror it here locally. */
#define OM_WAVE_N_TYPES 6

typedef struct {
    int behavior;
    int modifier;
    int hidden;
    int ambush_triggered;
    int hook_true;
    int base_transition_true;
    int last_issued_command_type;
    int objective_entered;
    int32_t faction_id;
    double hp_pct;
    int hp_pct_set;
    double hp_sum_start;
    int hp_sum_start_set;
    double threshold_noise;
    int threshold_noise_drawn;
    double timer_noise;
    int timer_noise_drawn;
    uint32_t phased_subgroups;
    int phased_subgroups_drawn;
    /* B13-8 (R-120-02, Q-120-02, Q-123-01): real group orders. faction_id_set
     * distinguishes a force the mission actually registered (om_macro_init_force)
     * from the R-120-04 default force 0 every om_macro_tick touches, whose
     * faction_id is otherwise indistinguishable from a real faction 0. */
    int faction_id_set;
    int has_contact;
    double hp_sum_last_eval;
    int hp_sum_last_eval_set;
    double fallback_x, fallback_y;
    int fallback_set;
    /* last group order actually issued, so a later evaluation reissues only
     * on a changed target, a changed behavior, or a changed unit count
     * (reinforcements joining the force) -- never every evaluation. */
    int last_order_valid;
    int last_order_behavior;
    double last_order_x, last_order_y;
    uint32_t last_order_n;
    /* B1-2 (R-120-02): patrol loop anchor (squad centroid when patrol was first ordered) and
     * the waypoint it is heading for. */
    int patrol_anchor_set;
    double patrol_anchor_x, patrol_anchor_y;
    uint32_t patrol_idx;
} om_macro_force;

typedef struct {
    char name[OM_MACRO_BUS_NAME_CAP];
    int value;
    int in_use;
} om_macro_bus_flag;

typedef struct {
    uint32_t force_id;
    char name[OM_MACRO_BUS_NAME_CAP];
} om_macro_hook_bind;

typedef struct {
    om_macro_force forces[OM_MACRO_MAX_FORCES];
    uint32_t n_forces;

    om_macro_bus_flag bus_flags[OM_MACRO_MAX_BUS_FLAGS];
    uint32_t n_bus_flags;

    om_macro_hook_bind hook_binds[OM_MACRO_MAX_HOOK_BINDS];
    uint32_t n_hook_binds;

    uint64_t last_tick_evaluated;
    uint64_t prev_clock;
    int has_evaluated;

    om_replay_command replay[OM_MACRO_MAX_REPLAY];
    uint32_t n_replay;

    int session_capture_enabled;
    unsigned char capture_buf[OM_MACRO_CAPTURE_BUF_CAP];
    uint32_t capture_len;

    om_reinforcement_wave wave;
    int wave_set;
    int reinforcement_spawned;
    double spawn_x, spawn_y;
} om_macro_state;

static char g_macro_vocab[OM_MACRO_MAX_VOCAB][OM_MACRO_BUS_NAME_CAP];
static uint32_t g_macro_vocab_n;

static uint32_t om_macro_state_size_hook(const om_world *w);
static void om_macro_state_write_hook(const om_world *w, uint8_t *out);
static int om_macro_state_read_hook(om_world *w, const uint8_t *buf, uint32_t len);

static void om_macro_state_free(void *p) {
    free(p);
}

static om_macro_state *om_macro_st(om_world *w) {
    om_macro_state *st = (om_macro_state *)w->macro_state;
    if (!st) {
        st = (om_macro_state *)calloc(1, sizeof(om_macro_state));
        w->macro_state = st;
        w->macro_state_free = om_macro_state_free;
        w->macro_state_size = om_macro_state_size_hook;
        w->macro_state_write = om_macro_state_write_hook;
        w->macro_state_read = om_macro_state_read_hook;
    }
    return st;
}

/* force_id 0 always exists (the R-120-04 default-force evaluation): any
 * access bumps the high-water mark om_macro_tick loops over. */
static om_macro_force *om_macro_force_at(om_macro_state *st, uint32_t force_id) {
    if (force_id >= OM_MACRO_MAX_FORCES) return NULL;
    if (force_id >= st->n_forces) st->n_forces = force_id + 1;
    return &st->forces[force_id];
}

/* ALG-74: one uniform draw in +-noise_pct per force, held for the mission
 * (drawn once, cached; never re-rolled on later ticks). */
static void om_macro_ensure_noise(om_world *w, om_macro_force *f) {
    if (!f->threshold_noise_drawn) {
        f->threshold_noise = (2.0 * om_rng_draw(w) - 1.0) * OM_SCRIPT_NOISE_DEFAULT_PCT;
        f->threshold_noise_drawn = 1;
    }
    if (!f->timer_noise_drawn) {
        f->timer_noise = (2.0 * om_rng_draw(w) - 1.0) * OM_SCRIPT_TIMER_NOISE_DEFAULT_PCT;
        f->timer_noise_drawn = 1;
    }
}

static int om_macro_command_for_behavior(int behavior) {
    switch (behavior) {
        case OM_MACRO_ADVANCE: return OM_MACRO_CMD_ATTACK_MOVE;
        case OM_MACRO_DEFEND:  return OM_MACRO_CMD_MOVE;
        case OM_MACRO_PATROL:  return OM_MACRO_CMD_MOVE;
        case OM_MACRO_AMBUSH:  return OM_MACRO_CMD_MOVE;
        case OM_MACRO_RETREAT: return OM_MACRO_CMD_MOVE;
        default: return OM_MACRO_CMD_MOVE;
    }
}

static om_macro_bus_flag *om_macro_bus_find(om_macro_state *st, const char *name) {
    uint32_t i;
    for (i = 0; i < st->n_bus_flags; i++) {
        if (st->bus_flags[i].in_use && strcmp(st->bus_flags[i].name, name) == 0) return &st->bus_flags[i];
    }
    return NULL;
}

static om_macro_bus_flag *om_macro_bus_find_or_create(om_macro_state *st, const char *name) {
    om_macro_bus_flag *f = om_macro_bus_find(st, name);
    if (f) return f;
    if (st->n_bus_flags >= OM_MACRO_MAX_BUS_FLAGS) return NULL;
    f = &st->bus_flags[st->n_bus_flags++];
    strncpy(f->name, name, sizeof(f->name) - 1);
    f->name[sizeof(f->name) - 1] = '\0';
    f->value = 0;
    f->in_use = 1;
    return f;
}

/* ---- generated stubs from signatures.toml ---- */
void om_macro_bind_hook_flag(om_world *w, uint32_t p1, const char *p2) {
    om_macro_state *st = om_macro_st(w);
    om_macro_hook_bind *b;
    uint32_t i;
    for (i = 0; i < st->n_hook_binds; i++) {
        if (st->hook_binds[i].force_id == p1 && strcmp(st->hook_binds[i].name, p2) == 0) return;
    }
    if (st->n_hook_binds >= OM_MACRO_MAX_HOOK_BINDS) return;
    b = &st->hook_binds[st->n_hook_binds++];
    b->force_id = p1;
    strncpy(b->name, p2, sizeof(b->name) - 1);
    b->name[sizeof(b->name) - 1] = '\0';
}

uint32_t om_macro_bus_get_active_flags_count(om_world *w) {
    om_macro_state *st = om_macro_st(w);
    uint32_t i, n = 0;
    for (i = 0; i < st->n_bus_flags; i++) {
        if (st->bus_flags[i].in_use && st->bus_flags[i].value != 0) n++;
    }
    return n;
}

int om_macro_bus_get_flag(om_world *w, const char *p1) {
    om_macro_state *st = om_macro_st(w);
    om_macro_bus_flag *f = om_macro_bus_find(st, p1);
    return f ? f->value : 0;
}

void om_macro_bus_register_vocab(const char *p0) {
    uint32_t i;
    if (!p0) return;
    for (i = 0; i < g_macro_vocab_n; i++) {
        if (strcmp(g_macro_vocab[i], p0) == 0) return;
    }
    if (g_macro_vocab_n >= OM_MACRO_MAX_VOCAB) return;
    strncpy(g_macro_vocab[g_macro_vocab_n], p0, OM_MACRO_BUS_NAME_CAP - 1);
    g_macro_vocab[g_macro_vocab_n][OM_MACRO_BUS_NAME_CAP - 1] = '\0';
    g_macro_vocab_n++;
}

void om_macro_bus_set_flag(om_world *w, const char *p1, int p2) {
    om_macro_state *st = om_macro_st(w);
    om_macro_bus_flag *f = om_macro_bus_find_or_create(st, p1);
    if (f) f->value = p2;
}

void om_macro_enemy_leaves_trigger(om_world *w, uint32_t p1) {
    /* R-120-02: ambush never resets once triggered -- leaving the trigger
     * radius intentionally changes nothing about the force's state. */
    (void)w; (void)p1;
}

int om_macro_eval_hook_flag(om_world *w, uint32_t p1, const char *p2) {
    om_macro_state *st = om_macro_st(w);
    uint32_t i;
    int bound = 0;
    for (i = 0; i < st->n_hook_binds; i++) {
        if (st->hook_binds[i].force_id == p1 && strcmp(st->hook_binds[i].name, p2) == 0) { bound = 1; break; }
    }
    if (!bound) return 0;
    return om_macro_bus_get_flag(w, p2);
}

int om_macro_eval_timer_transition(uint64_t p0, uint64_t p1, double p2) {
    double effective = (double)p1 * (1.0 + p2);
    return (effective >= (double)p0) ? 1 : 0;
}

int om_macro_eval_transitions(om_world *w, uint32_t p1) {
    om_macro_state *st = om_macro_st(w);
    om_macro_force *f = om_macro_force_at(st, p1);
    if (!f) return -1;
    if (f->hook_true) return OM_MACRO_TRANS_HOOK;
    if (f->base_transition_true) return OM_MACRO_TRANS_THRESHOLD;
    return -1;
}

uint32_t om_macro_evaluation_interval_ticks(void) {
    return OM_SCRIPT_EVAL_INTERVAL_TICKS;
}

/* R-123-02: enemy commands enter the same replay stream as the player's,
 * force_id first. The macro layer holds no target position, so the target
 * fields are zero. */
static void om_macro_log_command(om_world *w, uint64_t tick, uint32_t force_id, int cmd) {
    om_replay_log_command(w, tick, force_id, (uint32_t)cmd, 0.0, 0.0, 0);
}

/* B13-8 (R-120-02, R-123-02/Q-123-01, R-124-02): the macro layer's real group
 * orders. Mission registration (csrc/mission.c om_mission_instantiate_map)
 * calls om_macro_init_force / om_macro_set_force_fallback_point once per
 * mission; every force this evaluation gathers had faction_id_set from that
 * call, so an un-registered force (every existing S-120/121/122/123/125 unit
 * test, which never call om_macro_init_force with a live mission) sees no
 * behavior change here at all -- see also: om_macro_tick below. */
#define OM_MACRO_ORDER_CAP 2048
/* Rounding slack on the contact-query radius, as OM_FOG_BOUND_SLACK in fog.c (no bible value). */
#define OM_MACRO_BOUND_SLACK 1e-9
/* B1-2: no bible value (R-120-02 says only "waypoints in a cycle"); local choices. */
#define OM_MACRO_PATROL_RADIUS 600.0
#define OM_MACRO_PATROL_WAYPOINTS 4
#define OM_MACRO_PATROL_ARRIVE 60.0

static uint32_t om_macro_collect_faction_units(om_world *w, int32_t faction_id, uint32_t *out, uint32_t cap) {
    uint32_t total = om_unit_count(w);
    uint32_t scanned = 0, n = 0, i;
    for (i = 0; scanned < total && i < (uint32_t)OM_MAX_UNITS; i++) {
        uint32_t uid = om_unit_id_at(w, i);
        if (!uid) continue;
        scanned++;
        if (om_unit_get_faction(w, uid) != faction_id) continue;
        if (!om_unit_alive(w, uid)) continue;
        if (n < cap) out[n++] = uid;
    }
    return n;
}

static double om_macro_centroid(om_world *w, const uint32_t *ids, uint32_t n, double *out_y) {
    double sx = 0.0, sy = 0.0;
    uint32_t i;
    for (i = 0; i < n; i++) {
        double x = 0.0, y = 0.0;
        om_unit_get_pos(w, ids[i], &x, &y);
        sx += x; sy += y;
    }
    *out_y = (n > 0) ? sy / (double)n : 0.0;
    return (n > 0) ? sx / (double)n : 0.0;
}

/* Only reissues when the destination, the behavior, or the commanded unit
 * count (reinforcements joining the force) has changed since the last order
 * this force was actually given -- never on every 40-tick evaluation. */
static int om_macro_target_changed(const om_macro_force *f, int behavior, double x, double y, uint32_t n) {
    if (!f->last_order_valid) return 1;
    if (f->last_order_behavior != behavior) return 1;
    if (f->last_order_x != x || f->last_order_y != y) return 1;
    if (f->last_order_n != n) return 1;
    return 0;
}

static void om_macro_remember_order(om_macro_force *f, int behavior, double x, double y, uint32_t n) {
    f->last_order_valid = 1;
    f->last_order_behavior = behavior;
    f->last_order_x = x;
    f->last_order_y = y;
    f->last_order_n = n;
}

static void om_macro_issue_group_orders(om_world *w, om_macro_force *f) {
    static uint32_t force_ids[OM_MACRO_ORDER_CAP];
    static uint32_t player_ids[OM_MACRO_ORDER_CAP];
    uint32_t n_force, n_player, i;
    double hp_sum = 0.0;
    int contact_now = 0;
    double dest_x = 0.0, dest_y = 0.0;
    int have_dest = 0;

    n_force = om_macro_collect_faction_units(w, f->faction_id, force_ids, OM_MACRO_ORDER_CAP);
    if (n_force == 0) return; /* force not yet spawned or wiped out: nothing to command */

    for (i = 0; i < n_force; i++) hp_sum += om_unit_get_hp(w, force_ids[i]);

    n_player = om_macro_collect_faction_units(w, om_player_faction(w), player_ids, OM_MACRO_ORDER_CAP);

    /* Contact (Q-120-02): took damage this evaluation (force hp sum fell
     * since the last evaluation)... */
    if (f->hp_sum_last_eval_set && hp_sum < f->hp_sum_last_eval) contact_now = 1;
    /* ...or any of its units has a visible player unit in range. */
    /* Grid candidates stand in for the old all-pairs scan: the any-of result is
     * the same because the candidates are the player units the scan considered
     * (the first OM_MACRO_ORDER_CAP in id order, so ids up to player_ids[n-1])
     * within the observer's largest possible effective radius (target elevation
     * 0); om_unit_can_see still decides each pair. */
    for (i = 0; i < n_force && !contact_now && !f->has_contact && n_player > 0; i++) {
        double fx = 0.0, fy = 0.0, r;
        uint32_t nc, k;
        static uint32_t cand_ids[OM_MACRO_ORDER_CAP];
        om_unit_get_pos(w, force_ids[i], &fx, &fy);
        r = om_unit_get_effective_sensor_radius_to_target_elevation(w, force_ids[i], 0) * (1.0 + OM_MACRO_BOUND_SLACK);
        nc = om_grid_query_circle_faction(w, om_player_faction(w), fx, fy, r, cand_ids, OM_MACRO_ORDER_CAP);
        if (nc > OM_MACRO_ORDER_CAP) nc = OM_MACRO_ORDER_CAP;
        for (k = 0; k < nc; k++) {
            if (cand_ids[k] > player_ids[n_player - 1]) break;
            if (om_unit_can_see(w, force_ids[i], cand_ids[k])) { contact_now = 1; break; }
        }
    }
    f->hp_sum_last_eval = hp_sum;
    f->hp_sum_last_eval_set = 1;
    if (contact_now) f->has_contact = 1; /* sticky, like ambush's trigger (R-120-02) */
    /* B1-3 (R-120-02): ambush holds until contact, then becomes advance_aggressive; the
     * advance branch below attack-moves at the player. */
    if (f->behavior == OM_MACRO_AMBUSH && f->has_contact) om_macro_trigger_ambush(w, (uint32_t)(f - om_macro_st(w)->forces));

    if (f->behavior == OM_MACRO_ADVANCE) {
        if (f->has_contact && n_player > 0) {
            dest_x = om_macro_centroid(w, player_ids, n_player, &dest_y);
            have_dest = 1;
        } else {
            om_vec2 ctr;
            if (om_objective_get_center(w, 0, &ctr)) {
                dest_x = ctr.x; dest_y = ctr.y; have_dest = 1;
            } else if (n_player > 0) {
                /* No objective placed: fall back to the player centroid, the
                 * same convention om_mission_check_external_reinforcements
                 * below uses for the wave's destination. */
                dest_x = om_macro_centroid(w, player_ids, n_player, &dest_y);
                have_dest = 1;
            }
        }
        if (have_dest && om_macro_target_changed(f, f->behavior, dest_x, dest_y, n_force)) {
            om_command_attack_move(w, force_ids, n_force, dest_x, dest_y);
            om_macro_remember_order(f, f->behavior, dest_x, dest_y, n_force);
        }
    } else if (f->behavior == OM_MACRO_DEFEND) {
        /* "Hold": move to the objective and stay there. */
        om_vec2 ctr;
        if (om_objective_get_center(w, 0, &ctr)) {
            dest_x = ctr.x; dest_y = ctr.y; have_dest = 1;
        }
        if (have_dest && om_macro_target_changed(f, f->behavior, dest_x, dest_y, n_force)) {
            om_command_move(w, force_ids, n_force, dest_x, dest_y);
            om_macro_remember_order(f, f->behavior, dest_x, dest_y, n_force);
        }
    } else if (f->behavior == OM_MACRO_RETREAT) {
        /* "Rout": move back toward the enemy spawn edge. */
        if (f->fallback_set) {
            dest_x = f->fallback_x; dest_y = f->fallback_y; have_dest = 1;
        }
        if (have_dest && om_macro_target_changed(f, f->behavior, dest_x, dest_y, n_force)) {
            om_command_move(w, force_ids, n_force, dest_x, dest_y);
            /* B1-U1: om_unit_get_order_destination reads only the order record om_unit_order_move writes. */
            for (i = 0; i < n_force; i++) om_unit_order_move(w, force_ids[i], dest_x, dest_y);
            om_macro_remember_order(f, f->behavior, dest_x, dest_y, n_force);
        }
    } else if (f->behavior == OM_MACRO_PATROL) {
        /* B1-2 (R-120-02): plain-move round a diamond of waypoints about the anchor. */
        static const double dx[OM_MACRO_PATROL_WAYPOINTS] = { 1.0, 0.0, -1.0, 0.0 };
        static const double dy[OM_MACRO_PATROL_WAYPOINTS] = { 0.0, 1.0, 0.0, -1.0 };
        double cy, cx = om_macro_centroid(w, force_ids, n_force, &cy);
        double cvw, cvh;
        om_move_get_canvas_size(w, &cvw, &cvh); /* A146: waypoints are clamped to [0, canvas] when it is set. */
        if (!f->patrol_anchor_set) {
            f->patrol_anchor_x = cx; f->patrol_anchor_y = cy; f->patrol_anchor_set = 1;
        }
        dest_x = f->patrol_anchor_x + dx[f->patrol_idx] * OM_MACRO_PATROL_RADIUS;
        dest_y = f->patrol_anchor_y + dy[f->patrol_idx] * OM_MACRO_PATROL_RADIUS;
        if (cvw > 0.0 && cvh > 0.0) {
            dest_x = dest_x < 0.0 ? 0.0 : (dest_x > cvw ? cvw : dest_x);
            dest_y = dest_y < 0.0 ? 0.0 : (dest_y > cvh ? cvh : dest_y);
        }
        if ((cx - dest_x) * (cx - dest_x) + (cy - dest_y) * (cy - dest_y) < OM_MACRO_PATROL_ARRIVE * OM_MACRO_PATROL_ARRIVE) {
            f->patrol_idx = (f->patrol_idx + 1) % OM_MACRO_PATROL_WAYPOINTS;
            dest_x = f->patrol_anchor_x + dx[f->patrol_idx] * OM_MACRO_PATROL_RADIUS;
            dest_y = f->patrol_anchor_y + dy[f->patrol_idx] * OM_MACRO_PATROL_RADIUS;
            if (cvw > 0.0 && cvh > 0.0) {
                dest_x = dest_x < 0.0 ? 0.0 : (dest_x > cvw ? cvw : dest_x);
                dest_y = dest_y < 0.0 ? 0.0 : (dest_y > cvh ? cvh : dest_y);
            }
        }
        if (om_macro_target_changed(f, f->behavior, dest_x, dest_y, n_force)) {
            om_command_move(w, force_ids, n_force, dest_x, dest_y);
            om_macro_remember_order(f, f->behavior, dest_x, dest_y, n_force);
        }
    }
    /* AMBUSH issues no order until it triggers. */
}

int om_macro_execute_behavior(om_world *w, uint32_t p1, int p2, int p3) {
    om_macro_state *st = om_macro_st(w);
    om_macro_force *f = om_macro_force_at(st, p1);
    int cmd;
    (void)p3;
    if (!f) return OM_MACRO_CMD_MOVE;
    cmd = om_macro_command_for_behavior(p2);
    f->last_issued_command_type = cmd;
    om_macro_log_command(w, st->last_tick_evaluated, p1, cmd);
    return cmd;
}

